module fsm (
    input clk,
    input reset,
    input x,
    input y,
    output reg z);

    parameter IDLE=0, WAIT=1, CHECK=2;
    reg [1:0] state, next;

    always @(posedge clk) begin
        if (reset) state <= IDLE;
        else state <= next;
    end

    always_comb begin
        case (state)
            IDLE: next = x ? WAIT : IDLE;
            WAIT: next = y ? CHECK : IDLE;
            CHECK: next = y ? WAIT : IDLE;
            default: next = 'x;
        endcase
    end

    assign z = (state == CHECK);

endmodule

