module top_module_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg enable_n;
    reg reset;
    wire [9:0] q;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    top_module dut (
        .clk(clk),
        .enable_n(enable_n),
        .reset(reset),
        .q(q)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

        begin
            reset = 1;
            enable_n = 1;
            #15;
            reset = 0;
            #5;
        end
        endtask
    task testcase001;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Checking initial reset value", test_num);
            reset_dut();

            #1;


            check_outputs(10'd0);
        end
        endtask

    task testcase002;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Basic increment (10 cycles)", test_num);
            reset_dut();
            enable_n = 0;
            repeat (10) @(posedge clk);
            #1;
            #1;

            check_outputs(10'd10);
        end
        endtask

    task testcase003;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Checking active-low enable (disabled state)", test_num);
            reset_dut();
            enable_n = 1;
            repeat (20) @(posedge clk);
            #1;

            #1;


            check_outputs(10'd0);
        end
        endtask

    task testcase004;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Intermittent enable toggle", test_num);
            reset_dut();

            enable_n = 0;
            repeat (5) @(posedge clk);

            enable_n = 1;
            repeat (10) @(posedge clk);

            enable_n = 0;
            repeat (3) @(posedge clk);

            #1;

            #1;


            check_outputs(10'd8);
        end
        endtask

    task testcase005;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: 10-bit rollover check (1024 cycles)", test_num);
            reset_dut();
            enable_n = 0;
            repeat (1024) @(posedge clk);
            #1;

            #1;


            check_outputs(10'd0);
        end
        endtask

    task testcase006;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Rollover plus one", test_num);
            reset_dut();
            enable_n = 0;
            repeat (1025) @(posedge clk);
            #1;

            #1;


            check_outputs(10'd1);
        end
        endtask

    task testcase007;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Reaching max value (1023)", test_num);
            reset_dut();
            enable_n = 0;
            repeat (1023) @(posedge clk);
            #1;
            #1;

            check_outputs(10'd1023);
        end
        endtask

    task testcase008;

        begin
            test_num = test_num + 1;
            $display("Testcase %0d: Asynchronous reset during operation", test_num);
            reset_dut();
            enable_n = 0;
            repeat (50) @(posedge clk);


            #3;
            reset = 1;
            #2;
            reset = 0;


            @(posedge clk);
            enable_n = 1;
            #1;

            #1;


            check_outputs(10'd0);
        end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("top_module Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();
        testcase006();
        testcase007();
        testcase008();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [9:0] expected_q;
        begin
            if (expected_q === (expected_q ^ q ^ expected_q)) begin
                $display("PASS");
                $display("  Outputs: q=%h",
                         q);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: q=%h",
                         expected_q);
                $display("  Got:      q=%h",
                         q);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, enable_n, reset, q);
    end

endmodule

