      end else if (counter == 200000000) begin
        leds_2 <= 15;
      end else if (counter == 400000000) begin
        leds_2 <= 0;
      end else if (counter == 800000000) begin
        leds_3 <= 15;
      end else if (counter == 1600000000) begin
        leds_3 <= 0;
        counter <= 0;
      end
    end
  end

endmodule

