module mealy_machine (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter M=0, N=1, O=2, P=3;

    always_comb begin
        case (state)
            M: next_state = in1 ? O : N;
            N: next_state = in2 ? P : M;
            O: next_state = in1 ? M : P;
            P: next_state = in2 ? N : O;
        endcase
    end

    always_comb begin
        case (state)
            M: out = 1;
            N: out = 0;
            O: out = 1;
            P: out = 0;
        endcase
    end

endmodule

