module debouncer (
    input clk,
    input noisy,
    output reg debounced
);
    reg [20:0] counter;
    reg stable_state;

    always @(posedge clk) begin
        if (noisy == stable_state) begin
            counter <= 0;
        end else if (counter == 21'd1000000) begin
            stable_state <= noisy;
            counter <= 0;
        end else begin
            counter <= counter + 1;
        end
    end

    assign debounced = stable_state;

endmodule

