module shift_register(CLK,RST,SI,Q);
input CLK,RST,SI;
output [3:0] Q;
reg [3:0] Q;

always@(posedge CLK or posedge RST) begin
	if (RST)
		Q <= 0;
	else
		Q <= {Q[2:0], SI};
end

endmodule

