      4'h7: SEG_buf <= 7'b0000111;
      4'h8: SEG_buf <= 7'b1111111;
      4'h9: SEG_buf <= 7'b1101111;
      default: SEG_buf <= 7'b0000000;
    endcase
  end 

  assign sout = SEG_buf;

endmodule

