module shift_register(
    input               clk         ,
    input               rst         ,
    input       [7:0]   data_in     ,
    input               shift_dir   ,
    input               load        ,

    output  reg [7:0]   data_out
);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            data_out <= 8'b0;
        end
        else if (load) begin
            data_out <= data_in;
        end
        else if (shift_dir) begin
            // Right shift
            data_out <= {1'b0, data_out[7:1]};
        end
        else begin
            // Left shift
            data_out <= {data_out[6:0], 1'b0};
        end
    end

endmodule

