module top_module (
  input in1,
  input in2,
  input [1:0] state,
  output reg [1:0] next_state,
  output reg out);parameter F=0, G=1, H=2;

    always_comb begin
        case (state)
            F: next_state = in1 ? H : G;
            G: next_state = in2 ? F : H;
            H: next_state = in2 ? G : F;
        endcase
    end

    assign out = (state == G);

endmodule

