module dual_port_ram_16bit_tb;

    // Testbench signals (sequential circuit)
    reg clk;
    reg [3:0] raddr;
    reg re;
    reg rst_n;
    reg [3:0] waddr;
    reg [15:0] wdata;
    reg we;
    wire [15:0] rdata;

    // Test tracking
    integer test_num;
    integer pass_count;
    integer fail_count;

    // Instantiate the DUT (Device Under Test)
    dual_port_ram_16bit dut (
        .clk(clk),
        .raddr(raddr),
        .re(re),
        .rst_n(rst_n),
        .waddr(waddr),
        .wdata(wdata),
        .we(we),
        .rdata(rdata)
    );

    // Clock generation (10ns period)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

        task reset_dut;

    begin
        rst_n = 0;
        we = 0;
        re = 0;
        waddr = 0;
        raddr = 0;
        wdata = 0;
        #20;
        rst_n = 1;
        #10;
    end
        endtask
    task testcase001;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Basic Write and Read", test_num);
        reset_dut();
        @(posedge clk);
        we <= 1;
        waddr <= 4'hA;
        wdata <= 16'h55AA;
        @(posedge clk);
        we <= 0;
        re <= 1;
        raddr <= 4'hA;
        @(posedge clk);
        re <= 0;
        #1;
        #1;

        check_outputs(16'h55AA);
    end
        endtask

    task testcase002;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Boundary Address Write/Read (Addr 15)", test_num);
        reset_dut();
        @(posedge clk);
        we <= 1;
        waddr <= 4'hF;
        wdata <= 16'hFFFF;
        @(posedge clk);
        we <= 0;
        re <= 1;
        raddr <= 4'hF;
        @(posedge clk);
        re <= 0;
        #1;
        #1;

        check_outputs(16'hFFFF);
    end
        endtask

    task testcase003;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Verify Reset clears RAM", test_num);
        reset_dut();
        @(posedge clk);
        we <= 1;
        waddr <= 4'h3;
        wdata <= 16'hBEEF;
        @(posedge clk);
        we <= 0;

        #2 rst_n = 0;
        #10 rst_n = 1;
        @(posedge clk);
        re <= 1;
        raddr <= 4'h3;
        @(posedge clk);
        re <= 0;
        #1;
        #1;

        check_outputs(16'h0000);
    end
        endtask

    task testcase004;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Simultaneous Port Operation", test_num);
        reset_dut();

        @(posedge clk);
        we <= 1; waddr <= 4'h1; wdata <= 16'h1111;
        @(posedge clk);

        we <= 1; waddr <= 4'h2; wdata <= 16'h2222;
        re <= 1; raddr <= 4'h1;
        @(posedge clk);
        we <= 0; re <= 0;
        #1;
        #1;

        check_outputs(16'h1111);
    end
        endtask

    task testcase005;

    begin
        test_num = test_num + 1;
        $display("Testcase %0d: Overwrite Data Check", test_num);
        reset_dut();
        @(posedge clk);
        we <= 1; waddr <= 4'h7; wdata <= 16'hAAAA;
        @(posedge clk);
        wdata <= 16'h5555;
        @(posedge clk);
        we <= 0; re <= 1; raddr <= 4'h7;
        @(posedge clk);
        re <= 0;
        #1;
        #1;

        check_outputs(16'h5555);
    end
        endtask

    // Test stimulus
    initial begin
        // Initialize
        test_num = 0;
        pass_count = 0;
        fail_count = 0;

        $display("========================================");
        $display("dual_port_ram_16bit Testbench");
        $display("========================================");


        testcase001();
        testcase002();
        testcase003();
        testcase004();
        testcase005();


// Print summary
        $display("\n========================================");
        $display("Test Summary");
        $display("========================================");
        $display("Tests Passed: %0d", pass_count);
        $display("Tests Failed: %0d", fail_count);
        $display("Total Tests:  %0d", pass_count + fail_count);
        $display("========================================");

        if (fail_count == 0)
            $display("ALL TESTS PASSED!");
        else
            $display("SOME TESTS FAILED!");

        $display("\nSimulation completed at time %0t", $time);
        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [15:0] expected_rdata;
        begin
            if (expected_rdata === (expected_rdata ^ rdata ^ expected_rdata)) begin
                $display("PASS");
                $display("  Outputs: rdata=%h",
                         rdata);
                pass_count = pass_count + 1;
            end else begin
                $display("FAIL");
                $display("  Expected: rdata=%h",
                         expected_rdata);
                $display("  Got:      rdata=%h",
                         rdata);
                fail_count = fail_count + 1;
            end
        end
    endtask

    // Timeout watchdog
    initial begin
        #1000000; // 1ms timeout
        $display("\nERROR: Simulation timeout!");
        $finish;
    end

    // Optional: Waveform dump for debugging
    initial begin
        $dumpfile("wave.vcd");
        $dumpvars(0,clk, raddr, re, rst_n, waddr, wdata, we, rdata);
    end

endmodule

